// 独立回复段逐原件编码；旧拜帖1不追加空字段，派生本人索引不持久化。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "visit_reply_state.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "resident/domains/interaction/interaction_source_projection.hpp"
#include "resident/domains/interaction/s3_leaf_life_codec.hpp"
#include <set>
namespace hanmo::resident {namespace {
template<class A>Status contact(A& a,VisitMessageContact& v){a.field("actor_id",v.actor_id);a.field("custodian_actor_id",v.custodian_actor_id);a.field("place_id",v.place_id);a.field("role_id",v.role_id);a.field("session_id",v.session_id);a.field("dialogue_id",v.dialogue_id);a.field("node_id",v.node_id);return a.field("tick",v.tick);}
template<class A>Status receipt(A& a,VisitReplyPlayerReceipt& v){a.field("result_id",v.result_id);a.field("request_actor_id",v.request_actor_id);a.field("request_sequence",v.request_sequence);return a.field("result_revision",v.result_revision);}
template<class A>Status authored(A& a,VisitReplyAuthoredOrigin& v){a.field("intent_id",v.intent_id);return a.field("reception_claim_fact_id",v.reception_claim_fact_id);}
template<class A>Status posted(A& a,VisitReplyPosted& v,Integer version){a.field("fact_id",v.fact_id);a.field("policy_id",v.policy_id);a.field("message_fact_id",v.message_fact_id);a.field("received_fact_id",v.received_fact_id);a.field("response",v.response);a.object("contact",[&](auto& c){return contact(c,v.contact);});auto r=a.optional("player_receipt",v.player_receipt,[](auto& c,auto& r){return receipt(c,r);});if(!r.ok)return r;if(visit_reply_authored_version(version))return a.optional("authored_origin",v.authored_origin,[](auto& c,auto& origin){return authored(c,origin);});return v.authored_origin?a.reject("VisitReplyAuthoredVersionRequired"):r;}
template<class A>Status collected(A& a,VisitReplyCollected& v){a.field("fact_id",v.fact_id);a.field("reply_fact_id",v.reply_fact_id);a.object("contact",[&](auto& c){return contact(c,v.contact);});return a.optional("player_receipt",v.player_receipt,[](auto& c,auto& r){return receipt(c,r);});}
template<class A>Status life(A&a,VisitReplyLifeSource&v){a.object("death_ref",[&](auto&c){return s3_leaf_life_codec::death(c,v.death_ref);});a.field("reply_fact_id",v.reply_fact_id);dynamic_codec::enumeration(a,"role",v.role,2);return a.object("effect",[&](auto&c){return s3_leaf_life_codec::fields(c,v.effect,3);});}
template<class A>Status state(A& a,VisitReplyState& s){a.field("version",s.version);if(!visit_reply_version(s.version))return a.reject("UnsupportedVisitReplyVersion");auto r=dynamic_codec::table(a,"posted",s.posted,[&](auto& c,auto& v){return posted(c,v,s.version);});if(!r.ok)return r;r=dynamic_codec::table(a,"collected",s.collected,[](auto& c,auto& v){return collected(c,v);});if(!r.ok)return r;if(visit_reply_life_version(s.version))return dynamic_codec::table(a,"life_sources",s.life_sources,[](auto&c,auto&v){return life(c,v);});return s.life_sources.empty()?r:a.reject("UnselectedVisitReplyLifeSources");}
// 独立JSON入口拒递归重键，不能利用后值覆盖本人的原决定或永久结果绑定。
Status unique(const BoundaryValue& v,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("VisitReplyTooDeep");if(const auto* fields=v.as<BoundaryValue::Dict>()){if(fields->size()>CodecVisitor::max_items)return common_failure("VisitReplyTooLarge");std::set<StableId> keys;for(const auto& f:*fields){if(!keys.insert(f.first).second)return common_failure("DuplicateVisitReplyField",f.first);auto r=unique(f.second,depth+1);if(!r.ok)return r;}}if(const auto* rows=v.as<BoundaryValue::Array>()){if(rows->size()>CodecVisitor::max_items)return common_failure("VisitReplyTooLarge");for(const auto& row:*rows){auto r=unique(row,depth+1);if(!r.ok)return r;}}return common_success();}
}
void rebuild_visit_reply_indexes(VisitReplyState& s){s.posted_by_author.clear();s.collected_by_sender.clear();for(const auto& row:s.posted.rows())s.posted_by_author[row.second.contact.actor_id].push_back(row.first);for(const auto& row:s.collected.rows())s.collected_by_sender[row.second.contact.actor_id].push_back(row.first);}
Status visit_visit_replies_checkpoint(CodecVisitor& c,VisitReplyState& s){auto r=state(c,s);if(r.ok&&c.reading())rebuild_visit_reply_indexes(s);return r;}
Status emit_visit_replies_fields(ProjectionWriter&w,const VisitReplyState&v){dynamic_projection::Archive a(w);return state(a,const_cast<VisitReplyState&>(v));}
BoundaryValue encode_visit_replies(const VisitReplyState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_visit_replies_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Outcome<VisitReplyState> decode_visit_replies(const BoundaryValue& v){auto r=unique(v);if(!r.ok)return {false,{},r.error};VisitReplyState s;dynamic_codec::JsonArchive a(v);r=state(a,s);if(r.ok)r=a.finish();if(!r.ok)return {false,{},r.error};rebuild_visit_reply_indexes(s);return {true,std::move(s),{}};}
Status emit_visit_reply_fact_fields(ProjectionWriter&w,const VisitReplyState&s,const StableId&id,const FactRecord*expected){dynamic_projection::Archive a(w);Status valid;StableId kind;const StableId*actual_id=nullptr;if(const auto*row=s.posted.find(id)){valid=posted(a,const_cast<VisitReplyPosted&>(*row),s.version);kind=visit_reply_posted_kind;actual_id=&row->fact_id;}else if(const auto*row=s.collected.find(id)){valid=collected(a,const_cast<VisitReplyCollected&>(*row));kind=visit_reply_collected_kind;actual_id=&row->fact_id;}else return common_failure("UnknownVisitReplyFact",id);if(!valid.ok)return valid;if(expected&&(!actual_id||*actual_id!=id||kind!=expected->kind))return common_failure("VisitReplyFactMismatch",id);w.field("kind",kind);w.text("domain",std::string_view(visit_reply_module));return w.status();}
Outcome<BoundaryValue> encode_visit_reply_fact(const VisitReplyState& s,const StableId& id){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_visit_reply_fact_fields(out,s,id);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
}
